head.b:skin:
:root {
  --card-bg: #1f2937;
  --card-border: #374151;
  --text-main: #f3f4f6;
  --text-muted: #9ca3af;
  --year-color: #60a5fa;
  --imdb-color: #fbbf24;
  --genre-color: #c084fc;
  --country-color: #34d399;
  --lang-color: #f472b6;
  --bg: #111827;
  --panel-bg: #243244;
}
* { box-sizing: border-box; }
html, body { overflow-x: hidden; max-width: 100%; }
body { margin:0; font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; background: var(--bg); color: var(--text-main); line-height:1.5; color-scheme: dark; }
header { padding: 16px 16px 4px; max-width: 960px; margin: 0 auto; }
header h1 { margin: 0 0 8px; font-size: 1.35rem; }
main { max-width: 960px; margin: 0 auto; padding: 0 12px 48px; }
section { background: var(--card-bg); border: 1px solid var(--card-border); border-radius: 12px; padding: 14px; margin-bottom: 14px; max-width: 100%; }
section h2 { font-size: 1rem; margin: 0 0 10px; padding-bottom: 8px; border-bottom: 1px solid var(--card-border); }

.range-row { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; flex-wrap: wrap; }
.range-row label { font-size: 0.85rem; color: var(--text-muted); }
.range-row input[type="number"], .range-row input[type="text"] { padding: 6px 8px; font-size: 0.85rem; border: 1px solid var(--card-border); border-radius: 6px; background: var(--card-bg); color: var(--text-main); }
.range-row input[type="number"] { width: 90px; }

.score-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 12px; }
.score-field { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.score-field label { font-size: 0.78rem; color: var(--text-muted); }
.score-field input { width: 100%; min-width: 0; padding: 8px 10px; font-size: 0.9rem; border: 1px solid var(--card-border); border-radius: 6px; background: var(--card-bg); color: var(--text-main); }

.ms { position: relative; margin-bottom: 56px; padding-top: 26px; min-height: 122px; }
.ms-label { position: absolute; top: 0; left: 0; right: 0; font-size: 0.85rem; font-weight: 600; margin: 0; line-height: 20px; }
.ms-box {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  display: grid;
  grid-template-columns: 1fr 30px;
  grid-template-rows: 1fr 1fr auto;
  column-gap: 6px;
  height: 96px;
  border: 1px solid var(--card-border);
  border-radius: 6px;
  padding: 4px 8px;
  background: var(--card-bg);
  cursor: text;
  align-items: stretch;
}
.ms-box:focus-within { border-color: var(--year-color); }
.ms-chips {
  grid-column: 1; grid-row: 1 / 3;
  min-width: 0;
  overflow-y: auto;
  display: flex; flex-wrap: wrap; gap: 4px; align-content: flex-start;
}
.ms-input {
  grid-column: 1; grid-row: 3;
  border: none; outline: none; background: transparent; color: var(--text-main);
  font-size: 0.85rem; padding: 4px 0; width: 100%;
}
.ms-arrow {
  grid-column: 2; grid-row: 3;
  align-self: end; justify-self: end;
  border: none; background: transparent; cursor: pointer;
  color: var(--text-muted); font-size: 0.85rem; padding: 2px 4px;
  width: 26px; height: 26px; line-height: 1;
}
.ms-arrow.open { color: var(--text-main); }
.ms-chip { display: inline-flex; align-items: center; gap: 4px; font-size: 0.75rem; padding: 2px 6px; border-radius: 4px; background: rgba(37, 99, 235, 0.15); color: var(--text-main); }
.ms-chip[data-state="exclude"] { background: rgba(220, 38, 38, 0.15); }
.ms-chip[data-state="include"]::before { content: "✓ "; font-weight: 700; }
.ms-chip[data-state="exclude"]::before { content: "× "; font-weight: 700; }
.ms-chip button { border: none; background: transparent; cursor: pointer; color: inherit; font-size: 0.75rem; padding: 0 2px; }
.ms-panel { position: absolute; z-index: 50; top: calc(100% + 4px); left: 0; right: 0; max-width: 100%; max-height: 260px; overflow-y: auto; background: var(--panel-bg); border: 1px solid var(--card-border); border-radius: 8px; box-shadow: 0 8px 24px rgba(0,0,0,0.5); display: none; }
.ms-panel.open { display: block; }
.ms-panel-head { display: flex; justify-content: flex-end; padding: 6px 8px; border-bottom: 1px solid var(--card-border); position: sticky; top: 0; background: var(--panel-bg); z-index: 1; }
.ms-select-all { font-size: 0.75rem; padding: 2px 8px; border: 1px solid var(--card-border); border-radius: 4px; background: transparent; color: var(--text-main); cursor: pointer; }
.ms-select-all[data-state="include"] { background: rgba(37, 99, 235, 0.2); }
.ms-select-all[data-state="exclude"] { background: rgba(220, 38, 38, 0.2); }
.ms-option { display: flex; align-items: center; justify-content: space-between; padding: 6px 10px; font-size: 0.82rem; color: var(--text-main); gap: 8px; }
.ms-option:hover { background: rgba(255,255,255,0.05); }
.ms-check { width: 24px; height: 24px; flex: 0 0 24px; border: 1px solid var(--card-border); border-radius: 4px; background: transparent; color: var(--text-main); cursor: pointer; font-size: 0.9rem; }
.ms-check[data-state="include"] { background: rgba(37, 99, 235, 0.25); border-color: var(--year-color); }
.ms-check[data-state="exclude"] { background: rgba(220, 38, 38, 0.25); border-color: #dc2626; }
.ms-suggestions { border-top: 1px solid var(--card-border); padding: 4px 0; }
.ms-suggestion { padding: 6px 10px; font-size: 0.8rem; cursor: pointer; color: var(--text-muted); }
.ms-suggestion:hover { background: rgba(255,255,255,0.05); color: var(--text-main); }
.ms-extra { position: absolute; top: 100%; left: 0; right: 0; margin-top: 6px; font-size: 0.78rem; color: var(--text-muted); z-index: 5; }
.ms-extra label { display: flex; align-items: center; gap: 6px; cursor: pointer; margin-bottom: 2px; }
.ms-extra input[type="checkbox"] { accent-color: var(--year-color); }

.search-mode { border: 1px solid var(--card-border); border-radius: 8px; padding: 10px 12px; margin-bottom: 12px; }
.search-mode legend { font-size: 0.85rem; font-weight: 600; padding: 0 4px; }
.search-mode label { display: flex; align-items: center; gap: 8px; font-size: 0.85rem; margin-bottom: 4px; cursor: pointer; }
.search-mode input[type="checkbox"] { accent-color: var(--year-color); }
.search-mode-hint { margin: 6px 0 0; font-size: 0.75rem; color: var(--text-muted); }

.csv-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.csv-row input[type="file"] { font-size: 0.8rem; }
#csvStatus { font-size: 0.78rem; color: var(--text-muted); }
#csvClear { border: 1px solid var(--card-border); background: transparent; color: var(--text-main); border-radius: 6px; padding: 4px 8px; cursor: pointer; font-size: 0.8rem; display: none; }

#searchBtn { display: block; width: 100%; padding: 12px; font-size: 0.95rem; font-weight: 600; background: var(--year-color); color: #fff; border: none; border-radius: 8px; cursor: pointer; margin-top: 4px; }
#searchBtn:hover { opacity: 0.9; }
#clearAllBtn { display: block; width: 100%; padding: 10px; font-size: 0.85rem; font-weight: 600; background: transparent; color: var(--text-main); border: 1px solid var(--card-border); border-radius: 8px; cursor: pointer; margin-bottom: 8px; }

.more-btn {
  padding: 10px 16px;
  border: 1px solid var(--card-border);
  background: transparent;
  color: var(--text-main);
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.85rem;
}
.more-btn:hover { background: rgba(255,255,255,0.06); }
.more-btn:disabled { opacity: 0.5; cursor: default; }

.film-card {
  position: relative;
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: 12px;
  padding: 16px;
  margin-bottom: 16px;
}
.film-refresh {
  position: absolute;
  top: 8px; right: 8px;
  width: 26px; height: 26px;
  padding: 0;
  border: 1px solid var(--card-border);
  border-radius: 6px;
  background: transparent;
  color: var(--text-muted);
  font-size: 0.95rem;
  line-height: 1;
  cursor: pointer;
  z-index: 2;
}
.film-refresh:hover { color: var(--text-main); background: rgba(255,255,255,0.06); }
.film-top { display: flow-root; }
.film-poster-wrap { float: left; margin: 0 12px 8px 0; }
.film-poster { width: 120px; height: 180px; object-fit: cover; border-radius: 8px; background: #374151; cursor: zoom-in; display: block; }
.film-top-info { min-width: 0; }
.film-title { font-size: 1.05rem; font-weight: 700; margin: 0 0 2px; line-height: 1.3; word-break: break-word; padding-right: 32px; }
.film-title a { color: var(--text-main); text-decoration: none; }
.film-title a:hover { text-decoration: underline; }
.film-title-tr { font-size: 0.85rem; color: var(--text-muted); margin-bottom: 6px; }
.film-meta-line { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; font-size: 0.82rem; }
.film-year { color: var(--year-color); font-weight: 700; }
.imdb-rating { color: var(--imdb-color); font-weight: 700; }
.imdb-votes { color: var(--text-muted); font-weight: 400; }
.film-genres { color: var(--genre-color); font-size: 0.8rem; }
.film-runtime { color: var(--text-muted); font-size: 0.8rem; }
.film-director { color: var(--text-main); font-size: 0.8rem; }
.film-countries { color: var(--country-color); font-size: 0.8rem; }
.film-watched-badge { display: inline-block; font-size: 0.72rem; font-weight: 600; color: #fbbf24; background: rgba(251, 191, 36, 0.15); padding: 2px 8px; border-radius: 4px; margin-top: 6px; }
.film-bottom { clear: both; padding-top: 8px; }
.film-actions { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 8px; }
.film-actions button { font-size: 0.78rem; padding: 4px 10px; border: 1px solid var(--card-border); background: transparent; color: var(--text-main); border-radius: 6px; cursor: pointer; }
.film-actions button:hover { background: rgba(255,255,255,0.06); }
.film-details { display: none; border-top: 1px dashed var(--card-border); padding-top: 10px; }
.film-details.open { display: block; }
.detail-row { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 12px; font-size: 0.82rem; padding: 2px 0; }
.detail-row .label { color: var(--text-muted); }
.detail-row .value { color: var(--text-main); font-weight: 500; text-align: right; word-break: break-word; }
.film-overview { margin-top: 10px; font-size: 0.85rem; line-height: 1.5; }
.person-link { color: var(--year-color); text-decoration: none; cursor: pointer; }
.person-link:hover { text-decoration: underline; }
.film-gallery { display: none; margin-top: 10px; grid-template-columns: repeat(auto-fill, minmax(110px, 1fr)); gap: 6px; }
.film-gallery.open { display: grid; }
.film-gallery img { width: 100%; height: 80px; object-fit: cover; border-radius: 6px; background: #374151; cursor: zoom-in; }
.film-gallery .gallery-link { display: block; }
.list-note { font-size: 0.78rem; color: #fbbf24; background: rgba(251, 191, 36, 0.12); padding: 6px 10px; border-radius: 6px; margin-bottom: 12px; }
.loading, .error, .empty { font-size: 0.85rem; color: var(--text-muted); padding: 8px 0; }
.error { color: #f87171; }

.lightbox {
  display: none;
  position: fixed; inset: 0;
  background: rgba(0,0,0,0.85);
  z-index: 999;
  align-items: center; justify-content: center;
  padding: 24px;
}
.lightbox.open { display: flex; }
.lightbox img { max-width: 100%; max-height: 100%; border-radius: 8px; }
.lightbox-close {
  position: absolute; top: 12px; right: 12px;
  width: 36px; height: 36px;
  border: none; border-radius: 50%;
  background: rgba(255,255,255,0.15); color: #fff;
  font-size: 1rem; cursor: pointer;
}

.progress { margin-bottom: 12px; }
.progress-bar { width: 100%; height: 10px; background: #374151; border-radius: 6px; overflow: hidden; }
.progress-fill { height: 100%; width: 0%; background: linear-gradient(90deg, #2563eb, #60a5fa); transition: width 0.3s ease; }
.progress-text { font-size: 0.78rem; color: var(--text-muted); margin-top: 4px; word-break: break-word; }

.ratio-row { margin-bottom: 12px; }
.ratio-head { display: flex; align-items: center; gap: 8px; font-size: 0.85rem; margin-bottom: 4px; }
.ratio-labels { display: flex; justify-content: space-between; font-size: 0.78rem; color: var(--text-muted); margin-bottom: 2px; }
.ratio-slider { width: 100%; }
.ratio-slider:disabled { opacity: 0.4; }
.ratio-value { font-size: 0.8rem; color: var(--year-color); font-weight: 600; }

.family-item { border: 1px solid var(--card-border); border-radius: 8px; padding: 10px; margin-bottom: 10px; }
.family-title { font-size: 0.85rem; font-weight: 600; margin: 0 0 6px; }
.family-subtitle { font-size: 0.75rem; color: var(--text-muted); margin: 6px 0 2px; }
.family-levels { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; margin-bottom: 6px; }
.family-levels label { font-size: 0.75rem; display: flex; align-items: center; gap: 4px; cursor: pointer; }
.family-invisible { font-size: 0.75rem; color: var(--text-muted); display: flex; align-items: center; gap: 6px; margin-top: 4px; }

/* Blogger widget alanı için isteğe bağlı kart görünümü */
.custom-body-section {
  max-width: 960px;
  margin: 14px auto 0;
  padding: 0 12px;
}
.custom-body-section .widget {
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: 12px;
  padding: 14px;
  margin-bottom: 14px;
}
.custom-body-section h2 { font-size: 1rem; margin: 0 0 10px; padding-bottom: 8px; border-bottom: 1px solid var(--card-border); }

@media (max-width: 480px) {
  header, main { padding-left: 10px; padding-right: 10px; }
  section { padding: 12px; }
  .film-card { padding: 12px; }
  .film-poster { width: 90px; height: 135px; }
  .score-grid { gap: 6px; }
  .family-levels { grid-template-columns: 1fr; }
}

body.script:
//
const API_BASE = "https://film-proxy.stavaft.workers.dev";
const TARGET_COUNT = 5;

function esc(s) {
  return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}
function norm(s) {
  return String(s || "").trim().toLowerCase()
    .replace(/İ/g, "i").replace(/I/g, "ı")
    .replace(/Ş/g, "ş").replace(/Ğ/g, "ğ")
    .replace(/Ü/g, "ü").replace(/Ö/g, "ö").replace(/Ç/g, "ç")
    .replace(/Â/g, "a").replace(/Î/g, "i").replace(/Û/g, "u")
    .replace(/\s+/g, " ");
}
function yearOf(m) { return Number(String(m.release_date || "").slice(0, 4)) || Number(m.year) || null; }
function formatVotes(v) {
  if (v == null) return "";
  const n = Number(String(v).replace(/[^\d]/g, ""));
  if (!n) return "";
  return n >= 1000 ? ((n / 1000).toFixed(n >= 10000 ? 0 : 1)) + "B" : String(n);
}
function posterUrl(m, size) {
  size = size || "w342";
  const p = m.original_poster_path || m.poster_path || m.poster || "";
  if (!p) return "";
  if (p.indexOf("http") === 0) return p;
  return "https://image.tmdb.org/t/p/" + size + p;
}
function googleUrl(title, year) {
  const q = ((title || "") + " " + (year || "")).trim();
  return "https://www.google.com/search?q=" + encodeURIComponent(q);
}
function profileUrl(path, size) {
  size = size || "w45";
  if (!path) return "";
  return "https://image.tmdb.org/t/p/" + size + path;
}
const COUNTRY_ABBR = {
  "united states of america": "USA", "amerika birleşik devletleri": "ABD",
  "united states": "USA", "abd": "ABD",
  "united kingdom": "UK", "birleşik krallık": "UK",
  "russian federation": "Rusya", "rusya federasyonu": "Rusya",
  "south korea": "Güney Kore", "güney kore": "Güney Kore",
  "north korea": "Kuzey Kore", "kuzey kore": "Kuzey Kore",
  "czech republic": "Çekya", "çek cumhuriyeti": "Çekya"
};
function shortCountry(name) {
  const n = norm(name);
  return COUNTRY_ABBR[n] || name;
}

const STATIC_OPTIONS = {
  story_period: [{ id: "bc", label: "Milattan önce" }].concat(
    Array.from({ length: 19 }, function(_, i) { return { id: "c" + (i + 1), label: (i + 1) + ". yüzyıl" }; }),
    [
      { id: "d1900", label: "1900'ler" }, { id: "d1910", label: "1910'lar" }, { id: "d1920", label: "1920'ler" },
      { id: "d1930", label: "1930'lar" }, { id: "d1940", label: "1940'lar" }, { id: "d1950", label: "1950'ler" },
      { id: "d1960", label: "1960'lar" }, { id: "d1970", label: "1970'ler" }, { id: "d1980", label: "1980'ler" },
      { id: "d1990", label: "1990'lar" }, { id: "d2000", label: "2000'ler" }, { id: "d2010", label: "2010'lar" },
      { id: "d2020", label: "2020'ler" }, { id: "future", label: "Geleceğe dair" }
    ]
  ),
  story_geography: [
    { id: "city", label: "Şehir" }, { id: "town", label: "Kasaba" }, { id: "village", label: "Köy" },
    { id: "mountain", label: "Dağlık ve yüksek kesimler" }, { id: "desert", label: "Çöl" }, { id: "steppe", label: "Bozkır" },
    { id: "forest", label: "Orman" }, { id: "seaside", label: "Deniz kenarı" }, { id: "riverside", label: "Nehir kenarı" },
    { id: "opensea", label: "Açık deniz" }, { id: "air", label: "Hava" }
  ],
  season: [
    { id: "spring", label: "İlkbahar" }, { id: "summer", label: "Yaz" },
    { id: "autumn", label: "Sonbahar" }, { id: "winter", label: "Kış" }
  ],
  character_traits: [
    { id: "male_main", label: "Erkek ana karakter" }, { id: "female_main", label: "Kadın ana karakter" },
    { id: "child_main", label: "Çocuk ana karakter" }, { id: "lgbt_main", label: "LGBT+ ana karakter" },
    { id: "male_support", label: "Erkek yan karakter" }, { id: "female_support", label: "Kadın yan karakter" },
    { id: "child_support", label: "Çocuk yan karakter" }, { id: "lgbt_support", label: "LGBT+ yan karakter" },
    { id: "male_extra", label: "Erkek figüran" }, { id: "female_extra", label: "Kadın figüran" },
    { id: "child_extra", label: "Çocuk figüran" }, { id: "lgbt_extra", label: "LGBT+ figüran" },
    { id: "young_main", label: "Genç ana karakter" }, { id: "young_support", label: "Genç yan karakter" },
    { id: "young_extra", label: "Genç figüran" }, { id: "middle_main", label: "Orta yaşlı ana karakter" },
    { id: "middle_support", label: "Orta yaşlı yan karakter" }, { id: "middle_extra", label: "Orta yaşlı figüran" },
    { id: "old_main", label: "Yaşlı ana karakter" }, { id: "old_support", label: "Yaşlı yan karakter" },
    { id: "old_extra", label: "Yaşlı figüran" }, { id: "disabled_main", label: "Engelli ana karakter" },
    { id: "disabled_support", label: "Engelli yan karakter" }, { id: "disabled_extra", label: "Engelli figüran" },
    { id: "animal", label: "Ana veya yan karakter bir hayvan" }
  ],
  aspect_ratio: [
    { id: "1:1", label: "1:1" }, { id: "4:3", label: "4:3" }, { id: "16:9", label: "16:9" },
    { id: "18:9", label: "18:9" }, { id: "21:9", label: "21:9" }
  ],
  narrative_style: [
    { id: "multi", label: "Farklı hikayelerin ayrı ayrı anlatımı" },
    { id: "reverse", label: "Sondan başa doğru giden hikaye" },
    { id: "linear", label: "Baştan sona giden hikaye" },
    { id: "flashback", label: "Ara ara geriye dönüşler yapan hikaye" },
    { id: "end_first", label: "Sonu önce anlatılıp başı sonra anlatılan hikaye" },
    { id: "mid_first", label: "Ortası önce anlatılıp, öncesi ve sonrası sonra anlatılan hikaye" },
    { id: "fast", label: "Çok fazla olayın olduğu hareketli hikaye" },
    { id: "slow", label: "Çok az olayın olduğu durgun hikaye" },
    { id: "no_end", label: "Sonu olmayan hikaye" },
    { id: "alt_end", label: "Alternatif sonlu hikaye" },
    { id: "alt_narr", label: "Alternatif anlatımlı hikaye" }
  ],
  production_process: [
    { id: "amateur", label: "Amatör film" }, { id: "indie", label: "Bağımsız film" },
    { id: "art", label: "Sanat filmi" }, { id: "big", label: "Büyük prodüksiyon" },
    { id: "bmovie", label: "B movie" }, { id: "avant", label: "Avangart film" },
    { id: "studio", label: "Stüdyo filmi" }, { id: "no_music", label: "Müziksiz film" },
    { id: "rare_music", label: "Nadir Müzikli Film" }, { id: "handheld", label: "Hareketli kamera kullanımı" },
    { id: "propaganda", label: "Propaganda filmi" }, { id: "dogme", label: "Dogme 95" }
  ],
  sound: [
    { id: "ambient", label: "Sürekli doğal ortam gürültüsü" },
    { id: "music", label: "Yoğun müzik kullanımı" },
    { id: "effects", label: "Yoğun gürültülü efekt kullanımı" },
    { id: "voiceover_ext", label: "Dış ses kullanımı" },
    { id: "voiceover_int", label: "İç ses kullanımı" },
    { id: "silent", label: "Sessiz film" },
    { id: "dubbed", label: "Ses dublajı çoğunlukla stüdyoda yapılmış" }
  ],
  reality: [
    { id: "true", label: "Tamamen gerçek olaylara sadık" },
