function syncSexDetails() {
  document.querySelectorAll('[data-family-key="sex_nudity"]').forEach(function(el) {
    var noneRadio = el.querySelector('input[name="int_sex_nudity"][value="none"]');
    var ms = el.querySelector('[data-ms][data-name="sex_details"]');
    var disabled = !!(noneRadio && noneRadio.checked);
    if (ms) {
      ms.style.pointerEvents = disabled ? "none" : "";
      ms.style.opacity = disabled ? "0.45" : "";
      if (disabled) {
        var panel = ms.querySelector(".ms-panel");
        if (panel) panel.classList.remove("open");
      }
    }
  });
}

var watchedList = [];
function parseWatchedCSV(text) {
  var lines = text.replace(/^\uFEFF/, "").trim().split(/\r?\n/);
  if (!lines.length) return [];
  var headers = lines[0].split(",").map(function(h) { return h.trim().replace(/^"|"$/g, ""); });
  var idx = function(name) { return headers.findIndex(function(h) { return h.toLowerCase() === name.toLowerCase(); }); };
  var iTitle = idx("Original Title"), iYear = idx("Year"), iConst = idx("Const"), iDir = idx("Directors");
  if (iTitle < 0) throw new Error("CSV'de 'Original Title' sütunu yok.");
  var splitLine = function(line) {
    var out = []; var cur = ""; var q = false;
    for (var i = 0; i < line.length; i++) {
      var c = line[i];
      if (c === '"') { if (q && line[i+1] === '"') { cur += '"'; i++; } else q = !q; }
      else if (c === "," && !q) { out.push(cur); cur = ""; }
      else cur += c;
    }
    out.push(cur);
    return out;
  };
  return lines.slice(1).map(function(line) {
    var cols = splitLine(line);
    return {
      originalTitle: (cols[iTitle] || "").trim(),
      year: parseInt(cols[iYear]) || null,
      imdbId: iConst >= 0 ? (cols[iConst] || "").trim() : "",
      directors: iDir >= 0 ? (cols[iDir] || "").trim() : ""
    };
  }).filter(function(r) { return r.originalTitle; });
}
function filterWatchedLocally(movies) {
  if (!watchedList.length) return movies;
  var titleKey = function(t, y) { return norm(t) + "|" + (y || 0); };
  var titleSet = new Set(watchedList.map(function(w) { return titleKey(w.originalTitle, w.year); }));
  var imdbSet = new Set(watchedList.filter(function(w) { return w.imdbId; }).map(function(w) { return w.imdbId; }));
  return movies.filter(function(m) {
    if (m.imdb_id && imdbSet.has(m.imdb_id)) return false;
    if (m.imdbID && imdbSet.has(m.imdbID)) return false;
    return !titleSet.has(titleKey(m.original_title || m.title, yearOf(m)));
  });
}
function verifyWatched(result) {
  var w = watchedList.find(function(x) { return x.imdbId && (x.imdbId === result.imdbID || x.imdbId === result.imdb_id); });
  if (!w) return { verified: false, reason: "IMDb ID eşleşmedi" };
  if (w.directors) {
    var a = norm(result.omdb_directors || "");
    var b = norm(w.directors);
    if (a && a.indexOf(b.split(",")[0].trim()) === -1) return { verified: false, reason: "Yönetmen eşleşmedi" };
  }
  return { verified: true, reason: "IMDb ID + yönetmen doğrulandı" };
}

function currentMode() {
  return {
    useWebResearch: (document.getElementById("useWebResearch") || {}).checked || false,
    useAI: (document.getElementById("useAI") || {}).checked || false
  };
}
function updateModeHint() {
  var mode = currentMode();
  var useWebResearch = mode.useWebResearch, useAI = mode.useAI;
  var el = document.getElementById("modeHint");
  if (!el) return;
  var msg = "";
  if (useWebResearch && useAI) msg = "En doğru sonuç: önce web'den kanıt toplanır, yetersizse AI devreye girer.";
  else if (useWebResearch && !useAI) msg = "Hızlı mod: yalnızca web kaynakları. AI'ya özgü alanlar boş kalabilir.";
  else if (!useWebResearch && useAI) msg = "AI modu: web kanıtı olmadan tahmin; doğruluk düşebilir.";
  else msg = "Yalnızca klasik kaynaklar (TMDB, OMDb, Wikidata, Commons). AI alanları boş kalır.";
  el.textContent = msg;
}

function collectFilters() {
  var filters = {};
  document.querySelectorAll("[data-ms]").forEach(function(root) {
    var name = root.dataset.name;
    if (name === "sex_details") return;
    var v = msGetValues(root);
    var conflict = (root.querySelector(".ms-conflict") || {}).checked || false;
    if (v.include.length || v.exclude.length) {
      filters[name] = { include: v.include, exclude: v.exclude, conflict: conflict };
    }
  });
  var num = function(id, def) { var el = document.getElementById(id); var v = el ? parseFloat(el.value) : NaN; return Number.isFinite(v) ? v : def; };
  filters.imdbMin = num("imdbMin", 0); filters.imdbMax = num("imdbMax", 10);
  filters.tmdbMin = num("tmdbMin", 0); filters.tmdbMax = num("tmdbMax", 10);
  filters.imdbVotesMin = num("imdbVotesMin", 0);
  filters.tmdbVotesMin = num("tmdbVotesMin", 0);
  filters.yearMin = num("yearMin", null); filters.yearMax = num("yearMax", null);
  filters.runtimeMin = num("runtimeMin", null); filters.runtimeMax = num("runtimeMax", null);
  var ratio = function(id, enabledId) {
    var en = document.getElementById(enabledId);
    if (!en || !en.checked) return null;
    var el = document.getElementById(id);
    return el ? parseFloat(el.value) : null;
  };
  var nr = ratio("nightRatio", "enableLight"); if (nr != null) filters.nightRatioMin = nr;
  var ir = ratio("indoorRatio", "enablePlace"); if (ir != null) filters.indoorRatioMin = ir;
  var dd = ratio("dialogueDensity", "enableDialogue"); if (dd != null) filters.dialogueDensityMin = dd;
  var cr = ratio("colorRatio", "enableColor"); if (cr != null) filters.colorRatioMin = cr;
  var lc = ratio("locationCount", "enablePlaceCount"); if (lc != null) filters.locationCountMin = lc;
  var mainMin = num("charMainMin", null), mainMax = num("charMainMax", null);
  var suppMin = num("charSuppMin", null), suppMax = num("charSuppMax", null);
  var extraMin = num("charExtraMin", null), extraMax = num("charExtraMax", null);
  if (mainMin != null || mainMax != null || suppMin != null || suppMax != null || extraMin != null || extraMax != null) {
    filters.characterDensity = { mainMin: mainMin, mainMax: mainMax, supportMin: suppMin, supportMax: suppMax, extraMin: extraMin, extraMax: extraMax };
  }
  var family = {};
  document.querySelectorAll("[data-family-key]").forEach(function(el) {
    var key = el.dataset.familyKey;
    var int = (el.querySelector('input[name="int_' + key + '"]:checked') || {}).value || "";
    var app = (el.querySelector('input[name="app_' + key + '"]:checked') || {}).value || "";
    var invEl = el.querySelector(".family-invisible-check");
    var inv = invEl ? invEl.checked : false;
    var details = null;
    if (key === "sex_nudity") {
      var ms = el.querySelector('[data-ms][data-name="sex_details"]');
      if (ms) {
        var v = msGetValues(ms);
        if (v.include.length || v.exclude.length) details = { include: v.include, exclude: v.exclude, conflict: (ms.querySelector(".ms-conflict") || {}).checked || false };
      }
    }
    if (int || app || details) family[key] = { intensity: int, approach: app, evaluateInvisible: inv, details: details };
  });
  if (Object.keys(family).length) filters.family_content = family;
  return filters;
}

function buildDiscoverParams(filters, page) {
  var params = new URLSearchParams();
  params.set("language", "tr-TR");
  params.set("page", String(page || 1));
  params.set("include_adult", "false");
  params.set("sort_by", "vote_average.desc");

  var vc = filters.tmdbVotesMin > 0
    ? filters.tmdbVotesMin
    : filters.imdbVotesMin > 0
      ? Math.max(200, Math.round(filters.imdbVotesMin / 10))
      : 200;
  params.set("vote_count.gte", String(vc));

  var validId = function(id) { return id != null && id !== "" && id !== "__space__" && id !== "__studio__"; };
  if (filters.genres && filters.genres.include && filters.genres.include.length) {
    var ids = filters.genres.include.map(function(g) { return g.id; }).filter(validId);
    if (ids.length) params.set("with_genres", ids.join(","));
  }
  if (filters.genres && filters.genres.exclude && filters.genres.exclude.length) {
    var ids2 = filters.genres.exclude.map(function(g) { return g.id; }).filter(validId);
    if (ids2.length) params.set("without_genres", ids2.join(","));
  }
  if (filters.original_language && filters.original_language.include && filters.original_language.include.length) {
    var id = filters.original_language.include[0] && filters.original_language.include[0].id;
    if (validId(id)) params.set("with_original_language", id);
  }
  if (filters.production_countries && filters.production_countries.include && filters.production_countries.include.length) {
    var ids3 = filters.production_countries.include.map(function(c) { return c.id; }).filter(validId);
    if (ids3.length) params.set("with_origin_country", ids3.join("|"));
  }
  if (filters.tmdbMin > 0) params.set("vote_average.gte", String(filters.tmdbMin));
  if (filters.tmdbMax < 10) params.set("vote_average.lte", String(filters.tmdbMax));
  if (filters.yearMin != null) params.set("primary_release_date.gte", filters.yearMin + "-01-01");
  if (filters.yearMax != null) params.set("primary_release_date.lte", filters.yearMax + "-12-31");
  if (filters.runtimeMin != null) params.set("with_runtime.gte", String(filters.runtimeMin));
  if (filters.runtimeMax != null) params.set("with_runtime.lte", String(filters.runtimeMax));

  return params;
}

async function runResearch(movies, filters, options) {
  options = options || {};
  var refresh = options.refresh || false;
  var forceAll = options.forceAll || false;
  var onProgress = options.onProgress;
  var mode = currentMode();
  var res = await fetch(API_BASE + "/research", {
    method: "POST",
    headers: { "Content-Type": "application/json", "Accept": "text/event-stream" },
    body: JSON.stringify({ movies: movies.slice(0, TARGET_COUNT), filters: filters, useWebResearch: mode.useWebResearch, useAI: mode.useAI, refresh: refresh, forceAll: forceAll })
  });
  if (!res.ok || !res.body) {
    var err = await res.json().catch(function() { return {}; });
    throw new Error(err.error || ("Araştırma hatası: " + res.status));
  }
  var reader = res.body.getReader();
  var decoder = new TextDecoder();
  var buffer = "";
  var collected = [];
  while (true) {
    var r = await reader.read();
    if (r.done) break;
    buffer += decoder.decode(r.value, { stream: true });
    var parts = buffer.split("\n\n");
    buffer = parts.pop() || "";
    for (var pi = 0; pi < parts.length; pi++) {
      var part = parts[pi];
      var lineArr = part.split("\n");
      var line = null;
      for (var li = 0; li < lineArr.length; li++) if (lineArr[li].indexOf("data: ") === 0) { line = lineArr[li]; break; }
      if (!line) continue;
      var msg;
      try { msg = JSON.parse(line.slice(6)); } catch { continue; }
      if (msg.type === "start") { if (onProgress) onProgress({ percent: 0, text: "Başlıyor (" + msg.total + " film)" }); }
      else if (msg.type === "step") {
        var pct = Math.round((msg.index / msg.total) * 100);
        var stageText = msg.stage === "zenginleştiriliyor"
          ? msg.title + " — kaynaklar çekiliyor (" + (msg.fields || []).join(", ") + ")"
          : msg.stage === "önbellekten" ? msg.title + " — önbellekten"
          : msg.title + " — okunuyor";
        if (onProgress) onProgress({ percent: pct, text: stageText });
      }
      else if (msg.type === "movie") {
        collected.push(msg.movie);
        var pct2 = Math.round(((msg.index + 1) / msg.total) * 100);
        if (onProgress) onProgress({ percent: pct2, text: (msg.movie.original_title || msg.movie.title) + " tamamlandı" });
      }
      else if (msg.type === "done") {
        var list = (msg.movies || collected).map(function(m) { return Object.assign({}, m, { ai_requested: mode.useAI, web_requested: mode.useWebResearch }); });
        return list;
      }
      else if (msg.type === "error") throw new Error(msg.message || "Bilinmeyen hata");
    }
  }
  return collected.map(function(m) { return Object.assign({}, m, { ai_requested: mode.useAI, web_requested: mode.useWebResearch }); });
}

function nameLink(name, profilePath) {
  if (profilePath) {
    var src = profileUrl(profilePath);
    return '<a href="#" class="person-link" data-person-src="' + esc(src) + '" data-person-name="' + esc(name) + '">' + esc(name) + '</a>';
  }
  return esc(name);
}
function personList(items, includeProfile) {
  if (includeProfile === undefined) includeProfile = true;
  if (!Array.isArray(items) || !items.length) return "";
  return items.map(function(it) {
    if (typeof it === "string") return esc(it);
    return includeProfile ? nameLink(it.name, it.profile_path) : esc(it.name);
  }).filter(Boolean).join(", ");
}

function renderFilmCard(m, filters) {
  var original = m.original_title || m.title || "Bilinmeyen Film";
  var trTitle = m.title && m.title !== m.original_title ? m.title : "";
  var year = yearOf(m);
  var imdb = m.imdbRating || null;
  var votes = formatVotes(m.imdbVotes);
  var genres = Array.isArray(m.genres) ? m.genres.join(", ") : "";
  var countries = Array.isArray(m.production_countries) ? m.production_countries.map(shortCountry).join(", ") : "";
  var langs = Array.isArray(m.spoken_languages) ? m.spoken_languages.join(", ") : "";

  var directors = Array.isArray(m.director) && m.director.length
    ? m.director
    : (m.omdb_directors ? m.omdb_directors.split(",").map(function(s) { return { name: s.trim(), profile_path: null }; }) : []);
  var writers = Array.isArray(m.writers) ? m.writers : [];
  var actors = Array.isArray(m.cast) && m.cast.length
    ? m.cast
    : (Array.isArray(m.omdb_actors) ? m.omdb_actors.map(function(n) { return { name: n, profile_path: null }; }) : []);
  var producers = Array.isArray(m.producers) ? m.producers : [];
  var companies = Array.isArray(m.production_companies) ? m.production_companies : [];

  var topRows = [];
  if (year) topRows.push('<span class="film-year">' + esc(year) + '</span>');
  if (imdb) topRows.push('<span class="imdb-rating">IMDb ' + esc(imdb) + (votes ? ' <span class="imdb-votes">(' + esc(votes) + ' oy)</span>' : '') + '</span>');
  if (genres) topRows.push('<span class="film-genres">' + esc(genres) + '</span>');
  if (m.runtime != null) topRows.push('<span class="film-runtime">' + esc(m.runtime) + ' dk</span>');
  if (directors.length) topRows.push('<span class="film-director">Yönetmen: ' + personList(directors) + '</span>');
  if (countries) topRows.push('<span class="film-countries">' + esc(countries) + '</span>');

  var detailRows = [
    ["Dil", langs || null],
    ["Senarist", writers.length ? personList(writers) : null],
    ["Oyuncular", actors.length ? personList(actors) : null],
    ["Yapımcı", producers.length ? personList(producers) : null],
    ["Yapım Şirketi", companies.length ? companies.map(esc).join(", ") : null],
    ["TMDB Puanı", m.vote_average != null ? Number(m.vote_average).toFixed(1) : null],
    ["TMDB Oy", m.vote_count != null ? String(m.vote_count) : null],
    ["Yaş Sınırı", m.rated != null ? m.rated : null],
    ["Ödüller", m.awards != null ? m.awards : null],
    ["Metascore", m.metascore != null ? m.metascore : null],
    ["Hasılat", m.boxOffice != null ? m.boxOffice : null],
    ["Gece / Gündüz", m.night_ratio != null ? (m.night_ratio + "% / " + (m.day_ratio != null ? m.day_ratio : (100 - m.night_ratio)) + "%") : null],
    ["İç / Dış Mekân", m.indoor_ratio != null ? (m.indoor_ratio + "% / " + (100 - m.indoor_ratio) + "%") : null],
    ["Mekân Sayısı", m.location_count != null ? m.location_count : null],
    ["Diyalog Yoğunluğu", m.dialogue_density != null ? (m.dialogue_density + "%") : null],
    ["Renk / S&B", m.color_ratio != null ? (m.color_ratio + "% renkli") : null],
    ["En-Boy Oranı", m.aspect_ratio != null ? m.aspect_ratio : null],
    ["Mevsim", Array.isArray(m.season) ? m.season.join(", ") : (m.season != null ? m.season : null)],
    ["Hikâye Yeri", Array.isArray(m.story_locations) ? m.story_locations.join(", ") : null],
    ["Çekim Yeri", Array.isArray(m.filming_locations) && m.filming_locations.length ? m.filming_locations.join(", ") : null],
    ["Özgün Eser", m.original_work != null ? m.original_work : null],
    ["İlişkili Filmler", Array.isArray(m.related_films) && m.related_films.length ? m.related_films.join(", ") : null]
  ].filter(function(row) { return row[1] !== null && row[1] !== undefined && row[1] !== ""; });

  var detailHtml = detailRows.map(function(row) {
    return '<div class="detail-row"><span class="label">' + esc(row[0]) + '</span><span class="value">' + esc(row[1]) + '</span></div>';
  }).join("");
  var overview = m.overview || "";
  var overviewHtml = overview ? '<div class="film-overview"><p>' + esc(overview) + '</p></div>' : "";
  var poster = posterUrl(m);
  var gUrl = googleUrl(original, year);
  var watchedInfo = verifyWatched(m);
  var watchedBadge = watchedInfo.verified ? '<div class="film-watched-badge">İzlendi olarak doğrulandı (' + esc(watchedInfo.reason) + ')</div>' : "";

  return '<article class="film-card" data-movie-id="' + esc(m.id) + '">' +
    '<button type="button" class="film-refresh" data-refresh-id="' + esc(m.id) + '" title="Yenile" aria-label="Yenile">⟳</button>' +
    '<div class="film-top">' +
      '<div class="film-poster-wrap">' +
        (poster
          ? '<img class="film-poster" src="' + esc(poster) + '" alt="' + esc(original) + ' posteri" loading="lazy" data-full-src="' + esc(posterUrl(m, "w780")) + '" data-poster="1"/>'
          : '<div class="film-poster" aria-hidden="true"></div>') +
      '</div>' +
      '<div class="film-top-info">' +
        '<h3 class="film-title"><a href="' + esc(gUrl) + '" target="_blank" rel="noopener">' + esc(original) + '</a></h3>' +
        (trTitle ? '<div class="film-title-tr">' + esc(trTitle) + '</div>' : '') +
        '<div class="film-meta-line">' + topRows.join("") + '</div>' +
        watchedBadge +
      '</div>' +
    '</div>' +
    '<div class="film-bottom">' +
      '<div class="film-actions">' +
        '<button type="button" data-toggle="details" data-target="det-' + esc(m.id) + '">Daha fazla</button>' +
        '<button type="button" data-images-id="' + esc(m.id) + '" data-images-title="' + esc(original) + '" data-images-original="' + esc(m.original_title || original) + '">Görseller</button>' +
      '</div>' +
      '<div class="film-gallery" id="gal-' + esc(m.id) + '"></div>' +
      '<div class="film-details" id="det-' + esc(m.id) + '">' + detailHtml + overviewHtml + '</div>' +
    '</div>' +
  '</article>';
}

function renderFilmList(movies, container, filters) {
  filters = filters || {};
  if (!movies.length) {
    container.innerHTML = '<p class="empty">Sonuç bulunamadı.</p>';
    return;
  }
  var aiRequested = movies.some(function(m) { return m.ai_requested; });
  var aiAny = movies.some(function(m) { return m.ai_available === true; });
  var webRequested = movies.some(function(m) { return m.web_requested; });
  var webAny = movies.some(function(m) { return m.web_available === true; });
  var notes = [];
  if (aiRequested && !aiAny) notes.push("YZ devre dışı.");
  if (webRequested && !webAny) notes.push("Arama servisi devre dışı.");
  if (movies.some(function(m) { return m.unknown; })) notes.push("Bazı alanlar bilinmiyor.");
  var header = notes.length ? '<div class="list-note">' + notes.map(esc).join(" ") + '</div>' : "";
  container.innerHTML = header + movies.map(function(m) { return renderFilmCard(m, filters); }).join("");
}

var refreshClickAt = new Map();

function bindFilmCardEvents(container) {
  var lightbox = document.getElementById("lightbox");
  if (!lightbox) {
    lightbox = document.createElement("div");
    lightbox.id = "lightbox";
    lightbox.className = "lightbox";
    lightbox.innerHTML = '<button type="button" class="lightbox-close" aria-label="Kapat">✕</button><img alt=""/>';
    document.body.appendChild(lightbox);
    lightbox.addEventListener("click", function(e) {
      if (e.target === lightbox || e.target.classList.contains("lightbox-close")) {
        lightbox.classList.remove("open");
      }
    });
  }
  var lightboxImg = lightbox.querySelector("img");

  container.addEventListener("click", async function(e) {
    var person = e.target.closest("a.person-link");
    if (person) {
      e.preventDefault();
      var src = person.dataset.personSrc;
      if (src) { lightboxImg.src = src; lightboxImg.alt = person.dataset.personName || ""; lightbox.classList.add("open"); }
      return;
    }
    var poster = e.target.closest("img.film-poster");
    if (poster && poster.dataset.fullSrc) {
      lightboxImg.src = poster.dataset.fullSrc;
      lightboxImg.alt = poster.alt || "";
      lightbox.classList.add("open");
      return;
    }
    var galleryImg = e.target.closest(".film-gallery img");
    if (galleryImg) {
      lightboxImg.src = galleryImg.dataset.fullSrc || galleryImg.src;
      lightboxImg.alt = galleryImg.alt || "";
      lightbox.classList.add("open");
      return;
    }
    var btn = e.target.closest("button");
    if (!btn) return;
    if (btn.dataset.toggle) {
      var el = document.getElementById(btn.dataset.target);
      if (!el) return;
      el.classList.toggle("open");
      var isOpen = el.classList.contains("open");
      if (btn.dataset.toggle === "details") btn.textContent = isOpen ? "Daha az" : "Daha fazla";
      return;
    }
    if (btn.dataset.imagesId) {
      var card = btn.closest(".film-card");
      var gallery = card.querySelector(".film-gallery");
      if (!gallery) return;
      if (gallery.classList.contains("open")) {
        gallery.classList.remove("open");
        btn.textContent = "Görseller";
        return;
      }
      btn.disabled = true; btn.textContent = "Yükleniyor...";
      try {
        var params = new URLSearchParams({
          id: btn.dataset.imagesId,
          title: btn.dataset.imagesTitle || "",
          original_title: btn.dataset.imagesOriginal || ""
        });
        var res = await fetch(API_BASE + "/images?" + params.toString());
        if (!res.ok) throw new Error("Görseller: " + res.status);
        var data = await res.json();
        var images = Array.isArray(data.images) ? data.images.slice(0, 9) : [];
        if (!images.length) { gallery.innerHTML = '<p class="empty">Görsel bulunamadı.</p>'; }
        else {
          gallery.innerHTML = images.map(function(img) {
            return '<a href="' + esc(img.pageUrl || img.url) + '" target="_blank" rel="noopener" class="gallery-link">' +
              '<img src="' + esc(img.url) + '" alt="' + esc(img.title || "") + '" loading="lazy" data-full-src="' + esc(img.url) + '"/>' +
            '</a>';
          }).join("");
        }
        gallery.classList.add("open");
        btn.textContent = "Görselleri gizle";
      } catch (err) {
        console.error(err);
        gallery.innerHTML = '<p class="error">' + esc(err.message) + '</p>';
        gallery.classList.add("open");
        btn.textContent = "Görselleri gizle";
      } finally {
        btn.disabled = false;
        if (btn.textContent === "Yükleniyor...") btn.textContent = "Görseller";
      }
      return;
    }
    if (btn.dataset.refreshId) {
      var card2 = btn.closest(".film-card");
      var movieId = btn.dataset.refreshId;
      var now = Date.now();
      var last = refreshClickAt.get(movieId) || 0;
      var diff = now - last;
      if (diff < 1000) return;
      if (diff >= 1000 && diff < 4000) {
        refreshClickAt.set(movieId, 0);
        btn.disabled = true; btn.textContent = "Tam yenileniyor...";
        refreshMovie(movieId, card2, true).catch(function(err) { console.error(err); btn.textContent = "Hata"; })
          .finally(function() { btn.disabled = false; btn.textContent = "⟳"; });
        return;
      }
      refreshClickAt.set(movieId, now);
      btn.disabled = true; btn.textContent = "Yenileniyor...";
      refreshMovie(movieId, card2, false).catch(function(err) { console.error(err); btn.textContent = "Hata"; })
        .finally(function() { btn.disabled = false; btn.textContent = "⟳"; });
    }
  });
}

async function refreshMovie(movieId, cardEl, forceAll) {
  if (forceAll === undefined) forceAll = false;
  var movie = window.__lastMovies && window.__lastMovies.find(function(m) { return String(m.id) === String(movieId); });
  if (!movie) return;
  var filters = window.__lastFilters || {};
  var data = await runResearch([movie], filters, { refresh: true, forceAll: forceAll });
  var updated = data[0];
  if (!updated || !cardEl) return;
  var wrapper = document.createElement("div");
  wrapper.innerHTML = renderFilmCard(updated, filters);
  cardEl.replaceWith(wrapper.firstElementChild);
}

var MS_STATE = new WeakMap();
function msInit(root) {
  if (MS_STATE.get(root)) return;
  var state = { selected: new Map(), freeText: [] };
  MS_STATE.set(root, state);
  var box = root.querySelector(".ms-box");
  var chips = root.querySelector(".ms-chips");
  var input = root.querySelector(".ms-input");
  var arrow = root.querySelector(".ms-arrow");
  var panel = root.querySelector(".ms-panel");
  var optionsEl = root.querySelector(".ms-options");
  var selectAllBtn = root.querySelector(".ms-select-all");

  var name = root.dataset.name;
  var options = STATIC_OPTIONS[name] || [];
  if (!options.length) {
    try { options = JSON.parse(root.dataset.options || "[]"); } catch { options = []; }
  }

  var renderOptions = function() {
    var q = norm(input.value);
    var filtered = q ? options.filter(function(o) { return norm(o.label).indexOf(q) !== -1; }) : options;
    optionsEl.innerHTML = filtered.map(function(o) {
      var st = state.selected.get(String(o.id)) || "";
      return '<div class="ms-option" data-id="' + esc(o.id) + '">' +
        '<span>' + esc(o.label) + '</span>' +
        '<button type="button" class="ms-check" data-id="' + esc(o.id) + '" data-state="' + st + '">' + (st === "include" ? "✓" : st === "exclude" ? "×" : "") + '</button>' +
      '</div>';
    }).join("");
    if (!filtered.length) {
      optionsEl.innerHTML = '<div class="ms-empty" style="padding:8px 10px;font-size:0.8rem;color:var(--text-muted);">Eşleşen seçenek yok. Yazdığınız değer serbest değer olarak eklenecek.</div>';
    }
  };
  var renderChips = function() {
    var items = [];
    state.selected.forEach(function(st, id) {
      var opt = options.find(function(o) { return String(o.id) === String(id); });
      if (opt) items.push({ label: opt.label, id: id, st: st, free: false });
    });
    state.freeText.forEach(function(t) { items.push({ label: t, st: "include", free: true }); });
    chips.innerHTML = items.map(function(it) {
      return '<span class="ms-chip" data-state="' + it.st + '" ' + (it.free ? 'data-free="1"' : 'data-id="' + esc(it.id) + '"') + '>' +
        esc(it.label) + '<button type="button" data-remove="1" ' + (it.free ? 'data-free="1"' : 'data-id="' + esc(it.id) + '"') + '>✕</button>' +
      '</span>';
    }).join("");
  };
  var cycle = function(c) { return c === "" ? "include" : c === "include" ? "exclude" : ""; };

  optionsEl.addEventListener("click", function(e) {
    var btn = e.target.closest(".ms-check");
    if (!btn) return;
    e.stopPropagation();
    var id = String(btn.dataset.id);
    var next = cycle(state.selected.get(id) || "");
    if (next) state.selected.set(id, next); else state.selected.delete(id);
    input.value = "";
    renderOptions(); renderChips();
  });
  chips.addEventListener("click", function(e) {
    var btn = e.target.closest("button[data-remove]");
    if (!btn) return;
    if (btn.dataset.free) {
      var label = btn.closest(".ms-chip").childNodes[0].textContent.trim();
      state.freeText = state.freeText.filter(function(t) { return t !== label; });
    } else state.selected.delete(String(btn.dataset.id));
    renderOptions(); renderChips();
  });
  selectAllBtn.addEventListener("click", function(e) {
    e.stopPropagation();
    var cur = selectAllBtn.dataset.state || "";
    var next = cycle(cur);
    selectAllBtn.dataset.state = next;
    selectAllBtn.textContent = next === "include" ? "Tümünü seç ✓" : next === "exclude" ? "Tümünü seç ×" : "Tümünü seç";
    if (!next) state.selected.clear();
    else options.forEach(function(o) { state.selected.set(String(o.id), next); });
    input.value = "";
    renderOptions(); renderChips();
  });
  arrow.addEventListener("click", function(e) {
    e.stopPropagation();
    var willOpen = !panel.classList.contains("open");
    panel.classList.toggle("open", willOpen);
    arrow.classList.toggle("open", willOpen);
  });
  box.addEventListener("click", function(e) {
    if (e.target.closest(".ms-arrow")) return;
    if (e.target === input || !e.target.closest(".ms-chip")) {
      if (!panel.classList.contains("open")) {
        panel.classList.add("open");
        arrow.classList.add("open");
      }
    }
    input.focus();
  });
  document.addEventListener("click", function(e) {
    if (!root.contains(e.target)) {
      panel.classList.remove("open");
      arrow.classList.remove("open");
    }
  });

  input.addEventListener("input", renderOptions);
  input.addEventListener("keydown", function(e) {
    if (e.key !== "Enter" && e.key !== ",") return;
    e.preventDefault();
    var raw = input.value.trim();
    if (!raw) return;
    var parts = raw.split(";");
    var inc = (parts[0] || "").split(",").map(function(t) { return t.trim(); }).filter(Boolean);
    var exc = (parts[1] || "").split(",").map(function(t) { return t.trim(); }).filter(Boolean);
    inc.forEach(function(tok) {
      var opt = options.find(function(o) { return norm(o.label) === norm(tok); });
      if (opt) state.selected.set(String(opt.id), "include");
      else if (state.freeText.indexOf(tok) === -1) state.freeText.push(tok);
    });
    exc.forEach(function(tok) {
      var opt = options.find(function(o) { return norm(o.label) === norm(tok); });
      if (opt) state.selected.set(String(opt.id), "exclude");
      else if (state.freeText.indexOf("!" + tok) === -1) state.freeText.push("!" + tok);
    });
    input.value = "";
    renderOptions(); renderChips();
  });

  renderOptions(); renderChips();
}
function msGetValues(root) {
  var st = MS_STATE.get(root);
  if (!st) return { include: [], exclude: [] };
  var name = root.dataset.name;
  var options = STATIC_OPTIONS[name] || [];
  if (!options.length) { try { options = JSON.parse(root.dataset.options || "[]"); } catch { options = []; } }
  var include = [], exclude = [];
  st.selected.forEach(function(s, id) {
    var opt = options.find(function(o) { return String(o.id) === id; });
    var label = opt ? opt.label : id;
    if (s === "include") include.push({ id: id, label: label });
    else if (s === "exclude") exclude.push({ id: id, label: label });
  });
  st.freeText.forEach(function(t) {
    if (t.charAt(0) === "!") exclude.push({ id: null, label: t.slice(1) });
    else include.push({ id: null, label: t });
  });
  return { include: include, exclude: exclude };
}

function syncRatioLabels() {
  var pairs = [
    ["nightRatio", "gece", "gündüz"],
    ["indoorRatio", "iç mekân", "dış mekân"],
    ["locationCount", "tek mekân", "çoklu mekân"],
    ["dialogueDensity", "sessizlik", "yoğun konuşma"],
    ["colorRatio", "siyah beyaz", "renkli"]
  ];
  pairs.forEach(function(p) {
    var id = p[0], leftLabel = p[1], rightLabel = p[2];
    var el = document.getElementById(id);
    if (!el) return;
    var v = Number(el.value);
    var val = document.getElementById("val-" + id);
    var l = document.getElementById("lbl-" + id + "-left");
    var r = document.getElementById("lbl-" + id + "-right");
    if (val) val.textContent = "%" + v;
    if (l) l.textContent = leftLabel + " %" + (100 - v);
    if (r) r.textContent = rightLabel + " %" + v;
  });
}
function bindRatioToggles() {
  var map = {
    enableLight: "nightRatio",
    enablePlace: "indoorRatio",
    enablePlaceCount: "locationCount",
    enableDialogue: "dialogueDensity",
    enableColor: "colorRatio"
  };
  Object.entries(map).forEach(function(entry) {
    var enId = entry[0], sliderId = entry[1];
    var en = document.getElementById(enId);
    var sl = document.getElementById(sliderId);
    if (!en || !sl) return;
    en.addEventListener("change", function() { sl.disabled = !en.checked; });
    sl.addEventListener("input", syncRatioLabels);
    sl.disabled = !en.checked;
  });
  syncRatioLabels();
}

var searchState = {
  query: "",
  page: 1,
  totalPages: 1,
  filters: null,
  lastMovies: [],
  processedIds: new Set(),
  queue: []
};

async function fetchMoviesPage(opts) {
  var query = opts.query, filters = opts.filters, page = opts.page;
  if (query) {
    var params = new URLSearchParams();
    params.set("query", query);
    params.set("language", "tr-TR");
    params.set("page", String(page));
    var res = await fetch(API_BASE + "/tmdb/search/movie?" + params.toString());
    if (!res.ok) throw new Error("TMDB arama hatası: " + res.status);
    var data = await res.json();
    return { results: data.results || [], totalPages: data.total_pages || 1 };
  } else {
    var params2 = buildDiscoverParams(filters, page);
    var res2 = await fetch(API_BASE + "/tmdb/discover/movie?" + params2.toString());
    if (!res2.ok) throw new Error("TMDB discover hatası: " + res2.status);
    var data2 = await res2.json();
    return { results: data2.results || [], totalPages: data2.total_pages || 1 };
  }
}

async function performSearch() {
  var container = document.getElementById("results");
  var qEl = document.getElementById("searchQuery");
  var query = qEl ? qEl.value.trim() : "";
  if (!container) return;

  var filters = collectFilters();
  var hasQuery = query.length > 0;
  var hasFilters = Object.keys(filters).some(function(k) {
    var v = filters[k];
    if (v == null) return false;
    if (typeof v === "object") return true;
    if (typeof v === "number") return v > 0 && v !== 10;
    return false;
  });
  if (!hasQuery && !hasFilters) { container.innerHTML = '<p class="error">Film adı veya en az bir filtre girin.</p>'; return; }

  searchState.query = query;
  searchState.page = 1;
  searchState.totalPages = 1;
  searchState.filters = filters;
  searchState.lastMovies = [];
  searchState.processedIds = new Set();
  searchState.queue = [];

  container.innerHTML = '<div class="progress" id="progressBox"><div class="progress-bar"><div class="progress-fill" id="progressFill" style="width:0%"></div></div><div class="progress-text" id="progressText">Hazırlanıyor...</div></div><div id="resultsList"></div><div id="moreWrap" style="text-align:center;margin-top:12px;"></div>';

  await loadNextPage();
}

async function loadNextPage() {
  var listEl = document.getElementById("resultsList");
  var moreWrap = document.getElementById("moreWrap");
  if (!listEl) return;

  try {
    var batch = searchState.queue.slice(0, TARGET_COUNT);
    searchState.queue = searchState.queue.slice(TARGET_COUNT);

    while (batch.length < TARGET_COUNT && searchState.page <= (searchState.totalPages || 1)) {
      var pageData = await fetchMoviesPage({ query: searchState.query, filters: searchState.filters, page: searchState.page });
      var tp = pageData.totalPages || 1;
      searchState.totalPages = tp;
      var results = pageData.results || [];
      searchState.page += 1;
      if (!results.length) break;
      var fresh = results.filter(function(m) { return !searchState.processedIds.has(String(m.id)); });
      fresh.forEach(function(m) { searchState.processedIds.add(String(m.id)); });
      var visible = filterWatchedLocally(fresh);
      batch = batch.concat(visible);
    }

    var toResearch = batch.slice(0, TARGET_COUNT);
    searchState.queue = batch.slice(TARGET_COUNT);

    if (toResearch.length > 0) {
      window.__searchMovies = toResearch;
      var researched = await runResearch(toResearch, searchState.filters, {
        refresh: false,
        onProgress: function(p) {
          var fill = document.getElementById("progressFill");
          var txt = document.getElementById("progressText");
          if (fill) fill.style.width = p.percent + "%";
          if (txt) txt.textContent = "%" + p.percent + " — " + p.text;
        }
      });
      var passing = researched.filter(function(m) { return m.filter_match !== false; });
      searchState.lastMovies = searchState.lastMovies.concat(passing);
      window.__lastMovies = searchState.lastMovies;
      window.__lastFilters = searchState.filters;
    }

    var pb = document.getElementById("progressBox");
    if (pb) pb.remove();

    if (searchState.lastMovies.length) {
      renderFilmList(searchState.lastMovies, listEl, searchState.filters);
    } else {
      listEl.innerHTML = '<p class="empty">Sonuç bulunamadı.</p>';
    }

    if (moreWrap) {
      moreWrap.innerHTML = '<button type="button" id="moreBtn" class="more-btn">Aramayı sürdür</button>';
      var mb = document.getElementById("moreBtn");
      if (mb) mb.addEventListener("click", async function() {
        if (searchState.queue.length === 0 && searchState.page > (searchState.totalPages || 1)) {
          searchState.page = 1;
        }
        var btn = document.getElementById("moreBtn");
        if (btn) { btn.disabled = true; btn.textContent = "Yükleniyor..."; }
        await loadNextPage();
      });
    }
  } catch (e) {
    console.error(e);
    var pb2 = document.getElementById("progressBox");
    if (pb2) pb2.remove();
    if (listEl) listEl.insertAdjacentHTML("beforeend", '<p class="error">' + esc(e.message) + '</p>');
    if (moreWrap) {
      moreWrap.innerHTML = '<button type="button" id="moreBtn" class="more-btn">Aramayı sürdür</button>';
      var mb2 = document.getElementById("moreBtn");
      if (mb2) mb2.addEventListener("click", async function() {
        if (searchState.queue.length === 0 && searchState.page > (searchState.totalPages || 1)) {
          searchState.page = 1;
        }
        await loadNextPage();
      });
    }
  }
}

function clearAllFilters() {
  document.querySelectorAll("[data-ms]").forEach(function(root) {
    var st = MS_STATE.get(root);
    if (st) { st.selected.clear(); st.freeText = []; }
    var chips = root.querySelector(".ms-chips");
    if (chips) chips.innerHTML = "";
    var opts = root.querySelector(".ms-options");
    if (opts) opts.querySelectorAll(".ms-check").forEach(function(b) { b.dataset.state = ""; b.textContent = ""; });
    var sel = root.querySelector(".ms-select-all");
    if (sel) { sel.dataset.state = ""; sel.textContent = "Tümünü seç"; }
    var conf = root.querySelector(".ms-conflict");
    if (conf) conf.checked = false;
    var panel = root.querySelector(".ms-panel");
    if (panel) panel.classList.remove("open");
    var arrow = root.querySelector(".ms-arrow");
    if (arrow) arrow.classList.remove("open");
    var inp = root.querySelector(".ms-input");
    if (inp) inp.value = "";
  });
  ["imdbMin","tmdbMin","imdbVotesMin","tmdbVotesMin"].forEach(function(id) { var el = document.getElementById(id); if (el) el.value = "0"; });
  ["imdbMax","tmdbMax"].forEach(function(id) { var el = document.getElementById(id); if (el) el.value = "10"; });
  ["yearMin","yearMax","runtimeMin","runtimeMax","charMainMin","charMainMax","charSuppMin","charSuppMax","charExtraMin","charExtraMax"].forEach(function(id) { var el = document.getElementById(id); if (el) el.value = ""; });
  ["nightRatio","indoorRatio","locationCount","dialogueDensity","colorRatio"].forEach(function(id) { var el = document.getElementById(id); if (el) { el.value = "50"; el.disabled = true; } });
  ["enableLight","enablePlace","enablePlaceCount","enableDialogue","enableColor"].forEach(function(id) { var el = document.getElementById(id); if (el) el.checked = false; });
  document.querySelectorAll("[data-family-key]").forEach(function(el) {
    el.querySelectorAll('input[type="radio"]').forEach(function(r) { r.checked = false; r.dataset.wasChecked = ""; });
    var inv = el.querySelector(".family-invisible-check"); if (inv) inv.checked = false;
  });
  syncSexDetails();
  syncRatioLabels();
  var q = document.getElementById("searchQuery"); if (q) q.value = "";
  var r = document.getElementById("results"); if (r) r.innerHTML = "";
  searchState.lastMovies = [];
  searchState.page = 1;
  searchState.totalPages = 1;
  searchState.processedIds = new Set();
  searchState.queue = [];
}

document.addEventListener("DOMContentLoaded", async function() {
  renderFamilyGuide();

  var fillOptions = async function(name, endpoint, mapper) {
    var root = document.querySelector('[data-ms][data-name="' + name + '"]');
    if (!root) return;
    try {
      var res = await fetch(API_BASE + endpoint);
      if (!res.ok) return;
      var data = await res.json();
      STATIC_OPTIONS[name] = mapper(data);
    } catch (e) { console.warn(name + " listesi:", e.message); }
  };
  await Promise.all([
    fillOptions("genres", "/tmdb/genre/movie/list?language=tr-TR", function(d) { return (d.genres || []).map(function(g) { return { id: g.id, label: g.name }; }); }),
    fillOptions("original_language", "/tmdb/configuration/languages", function(d) { return (d || []).map(function(l) { return { id: l.iso_639_1, label: l.turkish_name || l.english_name || l.name }; }); }),
    fillOptions("production_countries", "/tmdb/configuration/countries?language=tr-TR", function(d) { return (d || []).map(function(c) { return { id: c.iso_3166_1, label: c.native_name || c.english_name || c.iso_3166_1 }; }); })
  ]);

  if (STATIC_OPTIONS.production_countries) {
    var regions = STATIC_OPTIONS.production_countries.map(function(c) { return { id: c.id, label: c.label }; });
    regions.push({ id: "__studio__", label: "Stüdyo" });
    STATIC_OPTIONS.story_locations = regions;
    STATIC_OPTIONS.filming_locations = regions;
  }

  document.querySelectorAll("[data-ms]").forEach(msInit);
  bindRatioToggles();
  var uw = document.getElementById("useWebResearch"); if (uw) uw.addEventListener("change", updateModeHint);
  var ua = document.getElementById("useAI"); if (ua) ua.addEventListener("change", updateModeHint);
  updateModeHint();

  var csvInput = document.getElementById("csvWatched");
  var csvClear = document.getElementById("csvClear");
  var csvStatus = document.getElementById("csvStatus");
  if (csvInput) {
    csvInput.addEventListener("change", function(e) {
      var file = e.target.files && e.target.files[0];
      if (!file) return;
      var reader = new FileReader();
      reader.onload = function() {
        try {
          watchedList = parseWatchedCSV(String(reader.result || ""));
          if (csvStatus) csvStatus.textContent = watchedList.length + " izlenen film yüklendi.";
          if (csvClear) csvClear.style.display = "inline-block";
        } catch (err) {
          if (csvStatus) csvStatus.textContent = "CSV hatası: " + err.message;
          if (csvClear) csvClear.style.display = "none";
        }
      };
      reader.onerror = function() { if (csvStatus) csvStatus.textContent = "CSV okunamadı."; };
      reader.readAsText(file, "UTF-8");
    });
  }
  if (csvClear) {
    csvClear.addEventListener("click", function() {
      watchedList = [];
      if (csvInput) csvInput.value = "";
      if (csvStatus) csvStatus.textContent = "CSV yüklenmedi.";
      csvClear.style.display = "none";
    });
  }

  var resultsContainer = document.getElementById("results");
  if (resultsContainer) bindFilmCardEvents(resultsContainer);
  var sb = document.getElementById("searchBtn"); if (sb) sb.addEventListener("click", performSearch);
  var sq = document.getElementById("searchQuery");
  if (sq) sq.addEventListener("keydown", function(e) { if (e.key === "Enter") performSearch(); });
  var ca = document.getElementById("clearAllBtn"); if (ca) ca.addEventListener("click", clearAllFilters);
});
